"use strict";
const state={token:sessionStorage.getItem("erp_v2_token")||"",user:null,organization:null,enabledModules:[],permissions:[],assets:[],workOrders:[],workOrderOptions:[],workEmployees:[],workServiceAreas:[],workCameraGroups:[],workIntake:[],workIntakeCapabilities:{canTriage:false},users:[],employees:[],employeeDepartments:[],employeePositions:[],assignableUsers:[],notifications:[],unread:0,roles:[],report:null,reportTab:"overview",reportSchedules:null,audit:null,auditFilters:{},selectedAssetId:null,selectedWorkId:null,view:"dashboard",workFilter:"open",intakeFilter:"all",workAreaFilter:"all"};
const viewModules={assets:"assets","work-orders":"work-orders",lighting:"lighting-operations",camera:"camera-operations",map:"map",fleet:"fleet",iot:"iot",finance:"finance",executive:"executive","integration-lab":"integration-lab",automation:"automation","ai-director":"ai-director",mobile:"field",structure:"structure",attendance:"attendance",safety:"safety",inventory:"inventory",maintenance:"maintenance",procurement:"procurement"};
const labels={dashboard:"Байгууллагын нүүр",assets:"Хөрөнгийн бүртгэл","work-orders":"Ажлын самбар",lighting:"Гэрэлтүүлэг",camera:"Камерын тасаг",reports:"Нэгдсэн тайлан",users:"Хэрэглэгчид",director:"Захирал",chief_engineer:"Ерөнхий инженер",accountant:"Нягтлан",hr:"Хүний нөөц",storekeeper:"Нярав",engineer:"Инженер",electric:"Цахилгааны инженер",safety:"ХАБЭА",camera_engineer:"Сүлжээний инженер",worker:"Ажилтан",new:"Шинэ",assigned:"Хуваарилсан",in_progress:"Гүйцэтгэж буй",pending_review:"Хянуулах",completed:"Дууссан",cancelled:"Цуцалсан",awaiting_safety_start:"ХАБЭА-н эхлэх зөвшөөрөл хүлээж байна",awaiting_management_start:"Ерөнхий инженерийн баталгаа хүлээж байна",execution:"Гүйцэтгэж байна",awaiting_safety_completion:"ХАБЭА-н эцсийн хяналт хүлээж байна",awaiting_management_completion:"Ерөнхий инженерээр хаалгах",normal:"Хэвийн",high:"Өндөр",emergency:"Яаралтай",low:"Бага",active:"Идэвхтэй",repair:"Засварт",inactive:"Идэвхгүй",retired:"Акталсан"};
const workflowActionLabels={safety_authorize_start:"Эхлүүлэх зөвшөөрөл өгөх",safety_return_start:"Шаардлага хангуулж буцаах",management_approve_start:"Ажил эхлүүлэхийг батлах",submit_completion:"Гүйцэтгэл дууссан",safety_accept_completion:"ХАБЭА хяналтаар зөвшөөрөх",safety_return_to_execution:"Засварт буцаах",safety_suspend_execution:"Ажлыг зогсоож, зөвшөөрөлд буцаах",management_close:"Ажил хаах",management_return_to_execution:"Гүйцэтгэлд буцаах"};
const transitions={new:["in_progress","cancelled"],assigned:["in_progress","cancelled"],in_progress:["pending_review","cancelled"],pending_review:["completed","in_progress"],completed:[],cancelled:[]};
const $=s=>document.querySelector(s);
const rememberedOrganization=localStorage.getItem("overva_organization");
if(rememberedOrganization)$("#loginForm").elements.organization.value=rememberedOrganization;
const loginQuery=new URLSearchParams(location.search);
if(loginQuery.get("organization"))$("#loginForm").elements.organization.value=loginQuery.get("organization");
if(loginQuery.get("identifier"))$("#loginForm").elements.identifier.value=loginQuery.get("identifier");
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const date=v=>v?new Intl.DateTimeFormat("mn-MN",{year:"numeric",month:"short",day:"numeric"}).format(new Date(v)):"—";
const dateTime=v=>v?new Intl.DateTimeFormat("mn-MN",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v)):"—";

async function api(path,options={}){const r=await fetch(path,{...options,headers:{"content-type":"application/json",...(state.token?{authorization:`Bearer ${state.token}`} :{}),...(options.headers||{})}});const body=await r.json().catch(()=>({}));if(r.status===401&&state.token)logout(false);if(!r.ok)throw new Error(body.error||"Сервертэй холбогдоход алдаа гарлаа");return body}
function toast(message,error=false){const el=$("#toast");el.textContent=message;el.className=`toast show${error?" error":""}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className="toast",2800)}
function initials(name){return String(name||"A").split(/\s+/).slice(0,2).map(w=>w[0]).join("").toUpperCase()}
function givenName(fullName){const parts=String(fullName||"").trim().split(/\s+/).filter(Boolean);return parts.at(-1)||"Хэрэглэгч"}
function moduleEnabled(code){return !code||state.enabledModules.includes(code)}
function applyModuleAccess(){document.querySelectorAll("[data-module]").forEach(el=>el.classList.toggle("module-disabled",!moduleEnabled(el.dataset.module)));const required=viewModules[state.view];if(required&&!moduleEnabled(required))state.view="dashboard"}
async function reloadModuleAccess(){const out=await api("/api/organizations/current");state.organization=out.organization;state.enabledModules=out.organization.enabledModules||[];state.permissions=out.permissions||[];applyModuleAccess()}

async function login(e){e.preventDefault();const f=new FormData(e.currentTarget),value=Object.fromEntries(f),btn=e.currentTarget.querySelector("button[type=submit]");$("#loginError").textContent="";btn.disabled=true;btn.textContent="Нэвтэрч байна...";try{const out=await api("/api/auth/login",{method:"POST",body:JSON.stringify(value)});state.token=out.token;sessionStorage.setItem("erp_v2_token",state.token);localStorage.setItem("overva_organization",value.organization);await loadSession()}catch(err){$("#loginError").textContent=err.message}finally{btn.disabled=false;btn.textContent="Нэвтрэх"}}
async function loadSession(){try{const[me,org]=await Promise.all([api("/api/auth/me"),api("/api/organizations/current")]);state.user=me.user;state.organization=org.organization;state.enabledModules=org.organization.enabledModules||me.user.enabled_modules||[];state.permissions=org.permissions||me.user.permissions||[];state.intakeFilter=({camera_engineer:"camera",electric:"lighting",safety:"other"})[state.user.role]||"all";state.workAreaFilter="all";state.workFilter=state.user.role==="chief_engineer"&&state.permissions.includes("work-orders.exception.decide")?"decision":"open";if(state.organization.builderConfigured===false&&state.permissions.includes("builder.manage"))state.view="builder";$("#loginView").classList.add("hidden");$("#appView").classList.remove("hidden");$("#usersNav").classList.toggle("hidden",state.user.role!=="director");$("#auditNav").classList.toggle("hidden",state.user.role!=="director");const reportOwner=(state.user.system_roles||[]).includes("owner"),canReadSchedules=state.permissions.includes("report-schedules.read");$("#reportsNav").classList.toggle("hidden",!reportOwner&&!canReadSchedules&&!["director","chief_engineer","accountant"].includes(state.user.role));$("#orgName").textContent=state.organization.name;$("#userName").textContent=state.user.full_name;$("#userRole").textContent=labels[state.user.role]||state.user.role;$("#userAvatar").textContent=initials(state.user.full_name);document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===state.view));applyModuleAccess();await refresh()}catch{logout(false)}}
function logout(show=true){if(show&&state.token)api("/api/auth/logout",{method:"POST"}).catch(()=>{});state.token="";state.user=null;state.organization=null;sessionStorage.removeItem("erp_v2_token");const form=$("#loginForm");if(show){localStorage.removeItem("overva_organization");history.replaceState({},"",location.pathname);form.reset()}$("#appView").classList.add("hidden");$("#loginView").classList.remove("hidden");if(show){form.elements.organization.focus();toast("Системээс гарлаа. Өөр байгууллагын кодоор нэвтэрч болно.")}}
async function refresh(){const calls=[["assignableUsers",api("/api/users/assignable")],["notifications",api("/api/notifications")]];if(moduleEnabled("assets"))calls.push(["assets",api("/api/assets")]);else state.assets=[];if(moduleEnabled("work-orders")){calls.push(["workOrders",api("/api/work-orders")]);calls.push(["workOrderOptions",api("/api/work-orders/options")]);calls.push(["workIntake",api("/api/work-orders/intake")])}else{state.workOrders=[];state.workOrderOptions=[];state.workEmployees=[];state.workServiceAreas=[];state.workCameraGroups=[];state.workIntake=[];state.workIntakeCapabilities={canTriage:false}}if(state.user?.role==="director")calls.push(["users",api("/api/users")]);const out=await Promise.all(calls.map(x=>x[1]));calls.forEach(([key],index)=>{const value=out[index];if(key==="notifications"){state.notifications=value.items;state.unread=value.unread}else if(key==="users"){state.users=value.items;state.roles=value.roles}else if(key==="workOrderOptions"){state.workOrderOptions=value.items;state.workEmployees=value.employees||[];state.workServiceAreas=value.serviceAreas||[];state.workCameraGroups=value.cameraGroups||[]}else if(key==="workIntake"){state.workIntake=value.items;state.workIntakeCapabilities=value.capabilities||{canTriage:false}}else state[key]=value.items});const validLightingArea=state.workServiceAreas.some(x=>x.code===state.workAreaFilter),validCameraGroup=state.workCameraGroups.some(x=>`camera:${x.code}`===state.workAreaFilter);if(state.workAreaFilter!=="all"&&!validLightingArea&&!validCameraGroup)state.workAreaFilter="all";applyModuleAccess();renderNotifications();render()}
function setView(view){const required=viewModules[view];if(required&&!moduleEnabled(required)){toast("Энэ модуль танай байгууллагад идэвхгүй байна",true);return}state.view=view;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===view));$("#breadcrumb").textContent=labels[view]||(view==="audit"?"Аудит журнал":view);render();if(view==="work-orders")refresh().catch(error=>toast(error.message,true));if(view==="lighting"&&typeof loadLighting==="function")loadLighting(true);if(view==="camera"&&typeof loadCamera==="function")loadCamera(true);if(view==="reports"&&state.reportTab==="overview"&&!state.report)loadReport();if(view==="reports"&&state.reportTab==="schedule"&&!state.reportSchedules)loadReportSchedules();if(view==="audit"&&!state.audit)loadAudit()}
function header(kicker,title,desc,action=""){return `<div class="page-header"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function empty(title,note){return `<div class="empty-state"><strong>${title}</strong><span>${note}</span></div>`}
function stat(title,value,note,icon,tone="blue"){return `<article class="stat-card ${tone}"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></article>`}

function isOverdue(x){return x.due_at&&!['completed','cancelled'].includes(x.status)&&new Date(x.due_at)<new Date()}
function dashboard(){const active=state.assets.filter(x=>x.status==="active").length,open=state.workOrders.filter(x=>!["completed","cancelled"].includes(x.status)),mine=open.filter(x=>x.assigned_to===state.user.id),overdue=open.filter(isOverdue),done=state.workOrders.filter(x=>x.status==="completed").length,recent=state.workOrders.slice(0,6),canCreateWork=state.permissions.includes("work-orders.create");return `${header("Өнөөдрийн тойм",`Сайн байна уу, ${esc(givenName(state.user.full_name))}`,`${esc(state.organization.name)} байгууллагын үйл ажиллагааны товч мэдээлэл.`)}<div class="stat-grid">${stat("Бүртгэлтэй хөрөнгө",state.assets.length,`${active} идэвхтэй`,"◇","blue")}${stat("Миний нээлттэй ажил",mine.length,"Танд хуваарилагдсан","✓","green")}${stat("Хугацаа хэтэрсэн",overdue.length,"Шуурхай анхаарах шаардлагатай","!","red")}${stat("Дууссан ажил",done,"Нийт баталгаажсан","↗","purple")}</div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Сүүлийн ажлын захиалгууд</h2><button data-go="work-orders">Бүгдийг харах →</button></div>${recent.length?`<div class="activity-list">${recent.map(x=>`<div class="activity-item"><i></i><div><strong>${esc(x.title)}</strong><span>${esc(x.assigned_name||x.asset_name||x.category)}</span></div><span class="badge ${x.status}">${labels[x.status]}</span></div>`).join("")}</div>`:empty("Ажлын захиалга алга","Шинэ ажил үүсгэж эхлээрэй.")}</section><section class="panel"><div class="panel-head"><h2>Шуурхай үйлдэл</h2></div><div class="quick-actions">${canCreateWork?`<button class="quick-action" data-open="workOrderDialog"><span class="stat-icon">+</span><div><b>Ажлын захиалга үүсгэх</b><span>Шинэ ажил бүртгэх</span></div></button>`:""}<button class="quick-action" data-open="assetDialog"><span class="stat-icon">◇</span><div><b>Хөрөнгө бүртгэх</b><span>Техник, тоног төхөөрөмж нэмэх</span></div></button></div></section></div>`}
function assets(){const rows=state.assets.map(x=>`<tr><td><button class="asset-link" data-asset-id="${x.id}">${esc(x.code)}</button><small>${esc(x.serial_number||"")}</small></td><td><strong>${esc(x.name)}</strong><small>${esc(x.location||"Байршилгүй")}</small></td><td>${esc(x.category)}</td><td>${x.responsible_name?`<strong>${esc(x.responsible_name)}</strong>`:"—"}</td><td><span class="badge ${x.status}">${labels[x.status]||x.status}</span></td></tr>`).join("");return `${header("Хөрөнгийн удирдлага","Хөрөнгийн бүртгэл","Техник, тоног төхөөрөмж болон объектын нэгдсэн жагсаалт.",'<button class="primary" data-open="assetDialog">+ Шинэ хөрөнгө</button>')}<div class="table-panel">${rows?`<table class="data-table"><thead><tr><th>Код / сериал</th><th>Нэр / байршил</th><th>Ангилал</th><th>Хариуцагч</th><th>Төлөв</th></tr></thead><tbody>${rows}</tbody></table>`:empty("Хөрөнгө бүртгэгдээгүй","Эхний хөрөнгөө нэмнэ үү.")}</div>`}
function statusControl(x){if(x.workflow_policy_id){const actions=x.available_actions||[];return `<div class="workflow-control"><span class="workflow-stage">${esc(labels[x.workflow_stage]||x.workflow_stage||labels[x.status])}</span>${actions.map(action=>`<button class="workflow-action ${action.includes("return")?"secondary":"primary"}" data-workflow-action="${action}" data-workflow-id="${x.id}">${esc(workflowActionLabels[action]||action)}</button>`).join("")}</div>`}const next=x.available_statuses||[];return next.length?`<select class="status-select" data-status-id="${x.id}"><option value="">${labels[x.status]}</option>${next.map(v=>`<option value="${v}">${labels[v]}</option>`).join("")}</select>`:`<span class="badge ${x.status}">${labels[x.status]}</span>`}
function assignmentControl(x){if(!x.can_assign)return x.assigned_name?`<strong>${esc(x.assigned_name)}</strong><small>${labels[x.assigned_role]||x.assigned_role}</small>`:"—";const candidates=state.assignableUsers.filter(u=>!x.department_id||u.department_id===x.department_id);return `<select class="assignee-select" data-assign-id="${x.id}"><option value="">Хуваарилаагүй</option>${candidates.map(u=>`<option value="${u.id}" ${u.id===x.assigned_to?"selected":""}>${esc(u.full_name)}</option>`).join("")}</select>`}
const workBoardLanes=[
  {key:"issues",title:"Асуудал ба хэрэгцээ",note:"Үзлэг, гомдол, тооллого, шууд хүсэлт"},
  {key:"decision",title:"Ерөнхий инженерийн шийдвэр",note:"Чиглүүлэлт болон гүйцэтгэлийн үлдэгдлийг шийдвэрлэнэ"},
  {key:"team",title:"Тасгийн ажил",note:"Хариуцагч сонгох эсвэл өөртөө авах"},
  {key:"start",title:"ХАБЭА эхлэх зөвшөөрөл",note:"Эрсдэл, хамгаалалт, checklist"},
  {key:"doing",title:"Гүйцэтгэж буй",note:"Талбарын бодит ажил"},
  {key:"safety-review",title:"ХАБЭА дуусгалтын шалгалт",note:"Хүлээн авах эсвэл засварт буцаах"},
  {key:"management-review",title:"Ерөнхий инженерийн хүлээн авалт",note:"Эцэслэн хаах эсвэл гүйцэтгэлд буцаах"},
  {key:"done",title:"Дууссан",note:"Хүлээн авч баталгаажуулсан ажил"},
  {key:"closed",title:"Хаагдсан түүх",note:"Дууссан болон цуцалсан бүх ажил"},
];
function workBoardLane(item){const stage=item.workflow_stage||item.status;if(item.status==="completed")return"done";if(item.status==="cancelled")return"closed";if(Number(item.pending_exception_count)>0)return"decision";if(stage==="awaiting_safety_start")return"start";if(stage==="awaiting_management_start")return"management-review";if(stage==="awaiting_safety_completion")return"safety-review";if(["pending_review","awaiting_management_completion"].includes(stage))return"management-review";if(item.routing_state==="team_backlog")return"team";if((item.assigned_to&&["assigned","in_progress"].includes(item.status))||["in_progress","execution"].includes(stage))return"doing";return"decision"}
const intakeDomainLabels={lighting:"Гэрэлтүүлэг",camera:"Камер",safety:"ХАБЭА илрүүлэлт",fleet:"Машин техник",facilities:"Аж ахуй"};
const intakeDomainIcons={lighting:"💡",camera:"📷",safety:"⚠",fleet:"🚗",facilities:"🏢"};
const workStreamLabels={core_service:"Үндсэн үйлчилгээ",internal_operation:"Дотоод үйл ажиллагаа"},assignmentKindLabels={normal:"Ердийн",special:"Тусгай үүрэг",emergency:"Яаралтай"};
function cameraGroupLabel(value){const code=String(value||"").trim();if(code==="98")return"Авто зам";if(code==="99")return"Аж ахуйн нэгж";if(/^\d+$/.test(code))return`${Number(code)}-р баг`;return code?`Бүлэг ${code}`:"Байршил тодорхойгүй"}
function cameraItemGroupCode(item){return String(item.camera_source_group_code||"").trim()}
function cameraGroupFilterValue(code){return`camera:${code}`}
function cameraWorkGroupCodes(){const codes=new Set((state.workCameraGroups||[]).map(item=>String(item.code||"").trim()).filter(Boolean));for(const item of [...state.workIntake,...state.workOrders]){if((intakeFilterDomain(item)==="camera"||workFilterDomain(item)==="camera")&&cameraItemGroupCode(item))codes.add(cameraItemGroupCode(item))}return[...codes].sort((a,b)=>(Number(a)||9999)-(Number(b)||9999)||a.localeCompare(b))}
function workIntakeCard(item){const related=Number(item.related_open_work_count||0),suggestion=item.suggested_work_type_id?`<div class="routing-suggestion"><b>Санал болгосон чиглэл</b><span>${esc(item.suggested_work_type_name)}${item.suggested_department_name?` · ${esc(item.suggested_department_name)}`:""}${item.suggested_workflow_name?" · зөвшөөрлийн урсгалтай":""}</span></div>`:"",domain=esc(item.domain||"other"),cameraGroup=item.domain==="camera"?cameraGroupLabel(cameraItemGroupCode(item)):"",icon=item.service_area_icon||intakeDomainIcons[item.domain]||"◆",area=cameraGroup||item.service_area_name||item.incident_type||intakeDomainLabels[item.domain]||item.domain;return `<article class="work-card intake-card ${domain}"><div class="work-card-top"><span class="intake-domain">${esc(icon)} ${esc(area)}</span><span class="badge ${item.status}">${item.status==="open"?"Шинэ":"Шалгаж буй"}</span></div><strong class="work-card-title-static">${esc(item.title)}</strong><small class="work-card-type">${esc(item.incident_type)}${item.location?` · ${esc(item.location)}`:""}</small>${suggestion}${item.object_name?`<div class="work-card-line"><span>Объект</span><b>${esc(item.object_code||item.object_name)}</b></div>`:""}<div class="work-card-line"><span>Үлдэгдэл</span><b>${Number(item.remaining_quantity||0)}</b></div><div class="work-card-line"><span>Бүртгэсэн</span><b>${date(item.reported_at)}</b></div>${related?`<button class="intake-related" data-history-id="${item.related_work_order_id}">⚠ Энэ объект дээр ${related} нээлттэй ажил байна</button>${state.workIntakeCapabilities.canAttachExisting?`<button class="secondary intake-attach" data-attach-intake="${item.id}" data-attach-work="${item.related_work_order_id}">Өмнөх ажилд хэмжих мөрөөр нэмэх</button>`:""}`:""}${state.workIntakeCapabilities.canTriage?`<button class="primary intake-convert" data-intake-id="${item.id}">${related?"Тусдаа шинэ ажил үүсгэх":"Тасгийн ажилд авах"} →</button>`:""}</article>`}
function workBoardCard(item){const stream=item.operational_stream?`<span class="work-purpose">${workStreamLabels[item.operational_stream]}</span>`:"",kind=item.assignment_kind&&item.assignment_kind!=="normal"?`<span class="work-purpose ${item.assignment_kind}">${assignmentKindLabels[item.assignment_kind]}</span>`:"",cameraGroup=workFilterDomain(item)==="camera"?cameraGroupLabel(cameraItemGroupCode(item)):"",area=cameraGroup?`<span class="work-purpose area">📷 ${esc(cameraGroup)}</span>`:item.service_area_name?`<span class="work-purpose area">${esc(item.service_area_icon||"◆")} ${esc(item.service_area_name)}</span>`:"",pending=Number(item.pending_exception_count||0),executors=item.executor_employee_names||[];return `<article class="work-card ${isOverdue(item)?"overdue":""}"><div class="work-card-top"><span class="badge ${item.priority}">${labels[item.priority]||item.priority}</span>${pending?`<span class="work-overdue">${pending} үлдэгдэл шийдвэрлэх</span>`:isOverdue(item)?'<span class="work-overdue">Хугацаа хэтэрсэн</span>':""}</div><button class="work-card-title" data-history-id="${item.id}">${esc(item.title)}</button><small class="work-card-type">${esc(item.work_type_name||item.category)}${item.department_name?` · ${esc(item.department_name)}`:""}</small><div class="work-purpose-row">${area}${stream}${kind}</div>${item.responsible_employee_name?`<div class="work-card-line"><span>Хариуцах</span><b>${esc(item.responsible_employee_name)}</b></div>`:""}${executors.length?`<div class="work-card-line"><span>Гүйцэтгэх</span><b>${esc(executors.join(", "))}</b></div>`:""}${item.asset_name?`<div class="work-card-line"><span>Объект</span><b>${esc(item.asset_code||item.asset_name)}</b></div>`:""}<div class="work-card-line"><span>Хугацаа</span><b>${date(item.due_at)}</b></div>${item.can_claim?`<button class="primary work-claim" data-claim-work="${item.id}">Ажил авах</button>`:""}<div class="work-card-section"><span>Системийн эрхтэй эзэн</span>${assignmentControl(item)}</div><div class="work-card-section work-card-status"><span>Одоогийн шат</span>${statusControl(item)}</div></article>`}
function intakeFilterDomain(item){return ["lighting","camera"].includes(item.domain)?item.domain:"other"}
function workFilterDomain(item){if(item.service_area_domain)return item.service_area_domain;const code=String(item.work_type_code||"");if(code.startsWith("camera-"))return"camera";if(code.startsWith("lighting-")||code.startsWith("traffic-signal-"))return"lighting";return"other"}
function workLanePresentation(lane){const selectedArea=state.intakeFilter==="lighting"&&state.workAreaFilter!=="all"?state.workServiceAreas.find(area=>area.code===state.workAreaFilter):null;if(selectedArea&&lane.key==="issues")return{title:selectedArea.intake_lane_title||`${selectedArea.name} — асуудал, хэрэгцээ`,note:`${selectedArea.name} чиглэлд бүртгэгдсэн гэмтэл, шаардлага`};if(selectedArea&&lane.key==="team")return{title:selectedArea.team_lane_title||`${selectedArea.name} — хэсгийн ажил`,note:"Сонгосон чиглэлийн инженер хариуцагчийг хуваарилна"};const selectedCameraGroup=state.intakeFilter==="camera"&&state.workAreaFilter.startsWith("camera:")?cameraGroupLabel(state.workAreaFilter.slice(7)):null;if(selectedCameraGroup&&lane.key==="issues")return{title:`${selectedCameraGroup} — камерын гэмтэл`,note:"Сонгосон байршлын бүлэгт бүртгэгдсэн камерын асуудал"};if(selectedCameraGroup&&lane.key==="team")return{title:`${selectedCameraGroup} — камерын ажил`,note:"Сүлжээний инженерийн гүйцэтгэх ажлын урсгал"};const focused={lighting:{issues:{title:"Гэрэлтүүлгийн тасагт ирсэн",note:"Авто зам, гэр хороолол, цамхаг, гэрлэн дохио"},team:{title:"Гэрэлтүүлгийн тасгийн ажил",note:"Цахилгааны инженер хариуцагчийг хуваарилна"}},camera:{issues:{title:"Камерын тасагт ирсэн",note:"Байршлын бүлгээр задарсан камер, сүлжээний гэмтэл"},team:{title:"Камерын тасгийн ажил",note:"Сүлжээний инженер хариуцагчийг хуваарилна"}},other:{issues:{title:"Бусад тасагт ирсэн",note:"Аж ахуй болон байгууллагын дотоод хэрэгцээ"},team:{title:"Хариуцах тасгийн ажил",note:"Тухайн нэгж хариуцагчийг хуваарилна"}}};return focused[state.intakeFilter]?.[lane.key]||lane}
function workAreaMatches(item){if(state.workAreaFilter==="all")return true;if(state.intakeFilter==="camera")return state.workAreaFilter===cameraGroupFilterValue(cameraItemGroupCode(item));return item.service_area_code===state.workAreaFilter}
function workIntakeTabs(){const counts={all:state.workIntake.length,lighting:0,camera:0,other:0};state.workIntake.forEach(item=>{counts[intakeFilterDomain(item)]+=1});const tabs=[{key:"all",label:"Бүгд",icon:""},{key:"lighting",label:"Гэрэлтүүлэг",icon:"💡"},{key:"camera",label:"Камер",icon:"📷"},{key:"other",label:"Бусад",icon:"◆"}],organizationScope=state.workIntakeCapabilities.scope==="organization",lightingItems=state.workIntake.filter(item=>intakeFilterDomain(item)==="lighting"),areaCounts=new Map(),unclassified=lightingItems.filter(item=>!item.service_area_code).length;lightingItems.forEach(item=>areaCounts.set(item.service_area_code,(areaCounts.get(item.service_area_code)||0)+1));const lightingTabs=state.intakeFilter==="lighting"?`<div class="work-area-row"><span class="work-intake-label">Гэрэлтүүлгийн чиглэл</span><div class="work-area-tabs"><button class="${state.workAreaFilter==="all"?"active":""}" data-work-area-filter="all">Бүгд <b>${lightingItems.length}</b></button>${state.workServiceAreas.filter(area=>area.domain==="lighting").map(area=>`<button class="${state.workAreaFilter===area.code?"active":""}" data-work-area-filter="${area.code}">${esc(area.icon)} ${esc(area.name)} <b>${areaCounts.get(area.code)||0}</b></button>`).join("")}</div>${unclassified?`<small class="work-area-warning">${unclassified} бүртгэлийн чиглэл эх өгөгдөлд тодорхойгүй тул “Бүгд”-д харагдана.</small>`:""}</div>`:"",cameraItems=state.workIntake.filter(item=>intakeFilterDomain(item)==="camera"),cameraCounts=new Map(),cameraUnclassified=cameraItems.filter(item=>!cameraItemGroupCode(item)).length;cameraItems.forEach(item=>{const code=cameraItemGroupCode(item);if(code)cameraCounts.set(code,(cameraCounts.get(code)||0)+1)});const cameraTabs=state.intakeFilter==="camera"?`<div class="work-area-row"><span class="work-intake-label">Камерын байршлын бүлэг</span><div class="work-area-tabs"><button class="${state.workAreaFilter==="all"?"active":""}" data-work-area-filter="all">Бүгд <b>${cameraItems.length}</b></button>${cameraWorkGroupCodes().map(code=>{const value=cameraGroupFilterValue(code);return`<button class="${state.workAreaFilter===value?"active":""}" data-work-area-filter="${esc(value)}">📍 ${esc(cameraGroupLabel(code))} <b>${cameraCounts.get(code)||0}</b></button>`}).join("")}</div>${cameraUnclassified?`<small class="work-area-warning">${cameraUnclassified} камерын бүртгэлийн байршлын бүлэг тодорхойгүй тул “Бүгд”-д харагдана.</small>`:""}</div>`:"";return `<div class="work-intake-toolbar"><span class="work-intake-label">Ажлын эх үүсвэр</span><div class="work-intake-tabs">${tabs.filter(tab=>organizationScope||tab.key==="all"||counts[tab.key]>0).map(tab=>`<button class="${state.intakeFilter===tab.key?"active":""}" data-intake-filter="${tab.key}">${tab.icon} ${tab.label}<b>${counts[tab.key]}</b></button>`).join("")}</div>${lightingTabs}${cameraTabs}<small>Тоонууд нь хөрөнгийн нийт бүртгэл биш, одоо урсгалд байгаа асуудлын тоо. Tab нь зөвхөн харагдацыг шүүнэ.</small></div>`}
function workOrders(){
  const closed=x=>["completed","cancelled"].includes(x.status),
    recentDone=state.workOrders.filter(x=>x.status==="completed").slice(0,20),
    canDecide=state.permissions.includes("work-orders.exception.decide"),
    scopedByArea=()=>["lighting","camera"].includes(state.intakeFilter),
    domainMatches=item=>(state.intakeFilter==="all"||workFilterDomain(item)===state.intakeFilter)&&(!scopedByArea()||workAreaMatches(item)),
    intakeMatches=item=>(state.intakeFilter==="all"||intakeFilterDomain(item)===state.intakeFilter)&&(!scopedByArea()||workAreaMatches(item)),
    baseFiltered=state.workOrders.filter(x=>state.workFilter==="decision"?workBoardLane(x)==="decision":state.workFilter==="mine"?x.assigned_to===state.user.id:state.workFilter==="overdue"?isOverdue(x):state.workFilter==="closed"?closed(x):!closed(x)||recentDone.includes(x)),
    filtered=state.workFilter==="open"?baseFiltered.filter(domainMatches):baseFiltered,
    visibleLanes=state.workFilter==="closed"?workBoardLanes.filter(x=>x.key==="closed"):state.workFilter==="decision"?workBoardLanes.filter(x=>x.key==="decision"):workBoardLanes.filter(x=>!["closed","decision"].includes(x.key)),
    exceptionCount=state.workOrders.filter(x=>workBoardLane(x)==="decision").length,
    decisionButton=canDecide?`<button class="management-queue ${state.workFilter==="decision"?"active":""}" data-work-filter="decision">Шийдвэр шаардсан <b>${exceptionCount}</b></button>`:"",
    actions=`<div class="page-actions"><div class="filter-tabs"><button class="${state.workFilter==="open"?"active":""}" data-work-filter="open">Нэгдсэн урсгал</button><button class="${state.workFilter==="overdue"?"active":""}" data-work-filter="overdue">Хугацаа хэтэрсэн</button><button class="${state.workFilter==="closed"?"active":""}" data-work-filter="closed">Бүх түүх</button></div>${decisionButton}</div>`,
    board=visibleLanes.map(lane=>{const presentation=workLanePresentation(lane),workItems=filtered.filter(item=>state.workFilter==="closed"?closed(item):workBoardLane(item)===lane.key),intakeItems=lane.key==="issues"&&state.workFilter==="open"?state.workIntake.filter(intakeMatches):[],count=workItems.length+intakeItems.length;return `<section class="work-lane ${lane.key}"><header><div><h2>${presentation.title}</h2><small>${presentation.note}</small></div><b>${count}</b></header><div class="work-lane-list">${intakeItems.map(workIntakeCard).join("")}${workItems.map(workBoardCard).join("")||(!intakeItems.length?'<p class="work-lane-empty">Энэ шатанд ажил алга.</p>':"")}</div></section>`}).join("");
  return `${header("АЖЛЫН УДИРДЛАГА","Байгууллагын нэгдсэн ажлын урсгал","Асуудал, хэрэгцээнээс эхлээд багийн гүйцэтгэл, хүлээн авалт хүртэл нэг мөрөөр харуулна.",actions)}${state.workFilter==="open"&&state.workIntakeCapabilities.canTriage?workIntakeTabs():""}<p class="work-board-help">${state.workFilter==="decision"?"Энд тодорхойгүй, тусгай, яаралтай ажил болон гүйцэтгэлээс үлдсэн хэмжээг дараагийн ажилд шилжүүлэх шийдвэр харагдана.":"Тасаг, үйлчилгээний чиглэл нь зөвхөн харагдацыг шүүнэ; ажлын баталгаатай урсгалыг өөрчлөхгүй. ХАБЭА шаардлагатай ажлын зөвшөөрөл, шалгалтыг систем алгасуулахгүй."}</p><div class="work-kanban ${state.workFilter}">${board}</div>`
}
function users(){const rows=state.users.map(x=>`<tr><td><strong>${esc(x.full_name)}</strong><small>${esc(x.username)}</small></td><td>${esc(x.email)}</td><td><span class="badge new">${labels[x.role]||x.role}</span></td><td><span class="badge ${x.active?"active":"inactive"}">${x.active?"Идэвхтэй":"Идэвхгүй"}</span></td><td>${x.id===state.user.id?'<small>Таны бүртгэл</small>':`<button class="secondary user-action" data-user-id="${x.id}" data-user-active="${x.active}">${x.active?"Идэвхгүй болгох":"Идэвхжүүлэх"}</button>`}</td></tr>`).join("");return `${header("Системийн удирдлага","Хэрэглэгчид","Байгууллагын хэрэглэгч, эрх болон нэвтрэх төлөвийг удирдана.",'<button class="primary" data-open="userDialog">+ Шинэ хэрэглэгч</button>')}<div class="table-panel">${rows?`<table class="data-table"><thead><tr><th>Хэрэглэгч</th><th>И-мэйл</th><th>Эрх</th><th>Төлөв</th><th>Үйлдэл</th></tr></thead><tbody>${rows}</tbody></table>`:empty("Хэрэглэгч алга","Шинэ хэрэглэгч үүсгэнэ үү.")}</div>`}
function reportIso(date){const offset=date.getTimezoneOffset();return new Date(date.getTime()-offset*60000).toISOString().slice(0,10)}
function reportPresetRange(preset){const today=new Date(),from=new Date(today),to=new Date(today);if(preset==="last_month"){from.setDate(1);from.setMonth(from.getMonth()-1);to.setDate(0)}else if(preset==="quarter"){from.setMonth(Math.floor(from.getMonth()/3)*3,1)}else if(preset==="year"){from.setMonth(0,1)}else from.setDate(1);return{from:reportIso(from),to:reportIso(to)}}
function defaultReportRange(){return reportPresetRange("month")}
async function loadReport(from,to){const range=from&&to?{from,to}:state.report?.period||defaultReportRange();try{state.report=await api(`/api/reports/overview?from=${encodeURIComponent(range.from)}&to=${encodeURIComponent(range.to)}`);if(state.view==="reports")render()}catch(err){toast(err.message,true)}}
function reportBars(items,labelKey){const max=Math.max(1,...items.map(item=>item.count));return items.length?`<div class="bar-list">${items.map(item=>`<div class="bar-row"><span>${esc(labels[item[labelKey]]||item[labelKey])}</span><div class="bar-track"><i style="width:${Math.round(item.count/max*100)}%"></i></div><b>${item.count}</b></div>`).join("")}</div>`:empty("Мэдээлэл алга","Сонгосон хугацаанд бүртгэл алга.")}
function reportDelta(value,previous){const delta=Number(value)-Number(previous);return `${delta>0?"+":""}${delta} · өмнөх үе ${previous}`}
function reportTrend(trend){const points=trend?.points||[],max=Math.max(1,...points.flatMap(point=>[point.created,point.completed]));return points.length?`<div class="report-trend">${points.map(point=>`<div class="trend-column" title="${point.bucket}: үүссэн ${point.created}, дууссан ${point.completed}"><div><i class="created" style="height:${Math.max(2,Math.round(point.created/max*100))}%"></i><i class="completed" style="height:${Math.max(2,Math.round(point.completed/max*100))}%"></i></div><small>${String(point.bucket).slice(5,10)}</small></div>`).join("")}</div><div class="trend-legend"><span><i class="created"></i>Үүссэн</span><span><i class="completed"></i>Дууссан</span></div>`:empty("Мэдээлэл алга","Сонгосон хугацаанд ажлын хөдөлгөөн алга.")}
function managementReport(){const range=state.report?.period||defaultReportRange(),toolbar=`<div class="report-actions"><div class="report-presets"><button type="button" data-report-preset="month">Энэ сар</button><button type="button" data-report-preset="last_month">Өмнөх сар</button><button type="button" data-report-preset="quarter">Энэ улирал</button><button type="button" data-report-preset="year">Энэ жил</button></div><form class="report-toolbar" id="reportFilterForm"><label>Эхлэх огноо<input name="from" type="date" value="${range.from}" required></label><label>Дуусах огноо<input name="to" type="date" value="${range.to}" required></label><button class="secondary" type="submit">Харах</button><button class="secondary" type="button" id="printReportButton">Хэвлэх / PDF</button><button class="primary" type="button" id="exportReportButton">Ажлын мөр CSV</button></form></div>`;if(!state.report)return `${header("УДИРДЛАГЫН ТАЙЛАН","Нэгдсэн тайлан","Энэ сарын баталгаатай үзүүлэлтийг ачаалж байна...",toolbar)}`;const r=state.report,s=r.work,p=r.comparison.work,people=r.people.participants.map(person=>`<tr><td><strong>${esc(person.full_name)}</strong><small>${esc(person.position||labels[person.job_role]||person.job_role)}${person.department?` · ${esc(person.department)}`:""}${person.active?"":" · Идэвхгүй"}</small></td><td>${person.assigned}</td><td class="completion-good">${person.completed}</td><td>${person.open_now}</td><td class="${person.overdue_now?"completion-warn":""}">${person.overdue_now}</td></tr>`).join(""),qualityItems=[];if(r.dataQuality.unknownStatusAtStart)qualityItems.push(`эхний төлөв сэргээгдэхгүй ${r.dataQuality.unknownStatusAtStart}`);if(r.dataQuality.unknownStatusAtEnd)qualityItems.push(`эцсийн төлөв сэргээгдэхгүй ${r.dataQuality.unknownStatusAtEnd}`);if(r.dataQuality.previousUnknownStatusAtStart)qualityItems.push(`өмнөх үеийн эхний төлөв сэргээгдэхгүй ${r.dataQuality.previousUnknownStatusAtStart}`);if(r.dataQuality.previousUnknownStatusAtEnd)qualityItems.push(`өмнөх үеийн эцсийн төлөв сэргээгдэхгүй ${r.dataQuality.previousUnknownStatusAtEnd}`);if(r.dataQuality.unassignedCreated)qualityItems.push(`хариуцагчгүй шинээр үүссэн ${r.dataQuality.unassignedCreated}`);if(r.dataQuality.unlinkedAssignees)qualityItems.push(`ажилтны master data-тай холбоогүй хариуцагч ${r.dataQuality.unlinkedAssignees}`);if(r.dataQuality.unknownCreatedAssignment)qualityItems.push(`үүсэх үеийн хариуцагчийн түүх unknown ${r.dataQuality.unknownCreatedAssignment}`);if(r.dataQuality.unknownCompletedAssignment)qualityItems.push(`дуусах үеийн хариуцагчийн түүх unknown ${r.dataQuality.unknownCompletedAssignment}`);return `<article class="report-document"><div class="report-print-head">${r.organization.logo_url?`<img src="${esc(r.organization.logo_url)}" alt="">`:""}<div><small>OVERVA · УДИРДЛАГЫН ТАЙЛАН</small><h1>${esc(r.organization.name)}</h1><p>${range.from} – ${range.to}</p></div><span>Ажлын ноорог<br>${new Date(r.report.generatedAt).toLocaleString("mn-MN")}</span></div>${header("УДИРДЛАГЫН ТАЙЛАН","Нэгдсэн тайлан",`${range.from} – ${range.to} · өмнөх ижил хугацаатай харьцуулсан ажлын тайлан.`,toolbar)}${qualityItems.length?`<div class="report-quality warning"><strong>Өгөгдлийн чанарын анхааруулга</strong><span>${qualityItems.join(" · ")}.</span></div>`:`<div class="report-quality"><strong>Түүхэн төлөв баталгаатай</strong><span>Үлдэгдэл, дууссан ажил болон хариуцагчийг өөрчлөлтийн түүхээс тооцов.</span></div>`}<div class="report-stat-grid">${stat("Эхний үлдэгдэл",s.opening_backlog,reportDelta(s.opening_backlog,p.opening_backlog),"↤")}${stat("Шинээр үүссэн",s.created,reportDelta(s.created,p.created),"+")}${stat("Тухайн үед дууссан",s.completed,reportDelta(s.completed,p.completed),"✓")}${stat("Эцсийн үлдэгдэл",s.closing_backlog,reportDelta(s.closing_backlog,p.closing_backlog),"↦")}${stat("Хугацаа хэтэрсэн",s.overdue,reportDelta(s.overdue,p.overdue),"!")}</div><div class="report-grid"><section class="report-panel report-wide"><h2>Ажлын хөдөлгөөн</h2><p class="report-help">Байгууллагын ${esc(r.trend.timeZone)} календарийн огноогоор үүссэн болон “Дууссан” төлөвт шилжсэн бодит түүхийг тооцов.</p>${reportTrend(r.trend)}</section><section class="report-panel"><h2>Тайлангийн төгсгөлийн ажлын төлөв</h2>${reportBars(r.statuses,"status")}</section><section class="report-panel"><h2>Одоогийн хөрөнгийн төлөв</h2><p class="report-help">Энэ нь хугацааны урсгал биш, ${new Date(r.assetSnapshot.asOf).toLocaleString("mn-MN")} үеийн snapshot.</p>${reportBars(r.assetSnapshot.statuses,"status")}</section><section class="report-panel report-wide"><h2>Ажилтай оролцсон хүмүүс</h2><p class="report-help">Оноолт, дахин оноолт, чөлөөлөлтийг append-only түүхээс ажилтны үндсэн бүртгэлтэй холбож тооцов. Түүхгүй хуучин төлөвийг unknown гэж анхааруулна.</p><div class="table-panel">${people?`<table class="performance-table"><thead><tr><th>Ажилтан</th><th>Хугацаанд оноосон</th><th>Хугацаанд дууссан</th><th>Одоо нээлттэй</th><th>Одоо хэтэрсэн</th></tr></thead><tbody>${people}</tbody></table>`:empty("Оролцогч алга","Сонгосон хугацаанд баталгаатай оноолт бүртгэгдээгүй байна.")}</div></section></div><footer class="report-foot">Эх сурвалж: OVERVA ажлын захиалга, append-only өөрчлөлтийн түүх, ажилтны үндсэн бүртгэл, хөрөнгийн одоогийн бүртгэл · Мэдээллийн таслалт ${new Date(r.report.dataCutoff).toLocaleString("mn-MN")}</footer></article>`}
const reportFrequencyLabels={daily:"Өдөр тутам",weekly:"7 хоног тутам",monthly:"Сар тутам",quarterly:"Улирал тутам",semiannual:"Хагас жил",annual:"Жил тутам",one_time:"Нэг удаа"};
function reportTabs(){const canOverview=(state.user?.system_roles||[]).includes("owner")||["director","chief_engineer","accountant"].includes(state.user?.role);if(!canOverview&&state.permissions.includes("report-schedules.read"))state.reportTab="schedule";return `<div class="report-tabs" role="tablist" aria-label="Тайлангийн хэсэг">${canOverview?`<button type="button" role="tab" data-report-tab="overview" aria-selected="${state.reportTab==="overview"}">Нэгдсэн тайлан</button>`:""}${state.permissions.includes("report-schedules.read")?`<button type="button" role="tab" data-report-tab="schedule" aria-selected="${state.reportTab==="schedule"}">Тайлангийн хуваарь</button>`:""}</div>`}
function reportScheduleDays(due,today){return Math.round((new Date(`${due}T00:00:00Z`)-new Date(`${today}T00:00:00Z`))/86400000)}
function reportScheduleStatus(item,today){if(!item.active)return `<span class="schedule-status inactive">Архивласан</span>`;const days=reportScheduleDays(item.nextDue,today);if(days<0)return `<span class="schedule-status overdue">${Math.abs(days)} хоног хэтэрсэн</span>`;if(days===0)return `<span class="schedule-status overdue">Өнөөдөр</span>`;if(days<=item.warnDays)return `<span class="schedule-status warning">${days} хоног үлдсэн</span>`;return `<span class="schedule-status ready">${days} хоног үлдсэн</span>`}
function reportScheduleDialog(){const users=state.assignableUsers.map(user=>`<option value="${user.id}">${esc(user.full_name)}</option>`).join("");return `<dialog id="reportScheduleDialog" class="schedule-dialog"><form method="dialog" class="schedule-dialog-head"><div><span class="eyebrow">ТАЙЛАГНАХ ҮҮРЭГ</span><h2 id="reportScheduleDialogTitle">Хуваарь нэмэх</h2></div><button type="submit" class="icon-button" aria-label="Хаах">×</button></form><form id="reportScheduleForm" class="schedule-form"><input type="hidden" name="id"><input type="hidden" name="expectedVersion"><label class="schedule-field-wide">Тайлангийн нэр<input name="name" maxlength="240" required placeholder="Жишээ: Сарын санхүүгийн тайлан"></label><label>Давтамж<select name="frequency" required>${Object.entries(reportFrequencyLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join("")}</select></label><label>Дараагийн хугацаа<input name="nextDue" type="date" required></label><label>Хариуцах хэрэглэгч<select name="responsibleUserId"><option value="">Сонгоогүй</option>${users}</select></label><label>Хариуцах нэгж / нэр<input name="responsibleLabel" maxlength="160" placeholder="Жишээ: Санхүүгийн алба"></label><label>Хүлээн авагч<input name="recipient" maxlength="240" placeholder="Байгууллага, удирдлага..."></label><label>Анхааруулах хоног<input name="warnDays" type="number" min="0" max="365" value="7" required></label><label class="schedule-field-wide">Тэмдэглэл<textarea name="note" maxlength="2000" rows="3" placeholder="Тайлангийн хамрах хүрээ, шаардлага..."></textarea></label><div class="schedule-dialog-actions schedule-field-wide"><button type="button" class="secondary" data-report-schedule-cancel>Цуцлах</button><button type="submit" class="primary">Хадгалах</button></div></form></dialog>`}
function reportScheduleView(){if(!state.reportSchedules||!state.reportScheduleMeta)return header("ТАЙЛАНГИЙН ХУВААРЬ","Хугацааны хяналт","Хуваарийг ачаалж байна...");const items=state.reportSchedules,meta=state.reportScheduleMeta,today=meta.today,active=items.filter(item=>item.active),overdue=active.filter(item=>reportScheduleDays(item.nextDue,today)<=0).length,upcoming=active.filter(item=>{const days=reportScheduleDays(item.nextDue,today);return days>0&&days<=7}).length,rows=items.map((item,index)=>{const owner=item.responsibleName||item.responsibleLabel||"—";return `<tr class="${item.active?"":"schedule-row-inactive"}"><td>${index+1}</td><td><strong>${esc(item.name)}</strong>${item.lastSubmittedOn?`<small>Сүүлд тэмдэглэсэн: ${esc(item.lastSubmittedOn)}</small>`:""}</td><td><span class="schedule-frequency">${esc(reportFrequencyLabels[item.frequency]||item.frequency)}</span></td><td><strong class="schedule-date">${esc(item.nextDue)}</strong></td><td>${reportScheduleStatus(item,today)}</td><td>${esc(owner)}</td><td>${esc(item.recipient||"—")}</td><td class="schedule-note" title="${esc(item.note)}">${esc(item.note||"—")}</td><td><div class="schedule-row-actions">${item.active&&meta.capabilities.canSubmit?`<button type="button" class="schedule-submit" data-report-schedule-submit="${item.id}">✓ Илгээсэн</button>`:""}${item.active&&meta.capabilities.canManage?`<button type="button" class="secondary" data-report-schedule-edit="${item.id}" aria-label="Засах">Засах</button><button type="button" class="danger-quiet" data-report-schedule-retire="${item.id}" aria-label="Архивлах">Архивлах</button>`:""}</div></td></tr>`}).join("");return `${header("ТАЙЛАН БА ХЯНАЛТ","Тайлангийн хуваарь",`Гаргах тайлангийн хугацаа, хариуцлага, илгээлтийн өөрчлөх боломжгүй түүх · ${esc(meta.timeZone)}`,meta.capabilities.canManage?'<button type="button" class="primary" data-report-schedule-create>+ Хуваарь нэмэх</button>':"")}<div class="schedule-stat-grid"><article><span>Нийт идэвхтэй</span><strong>${active.length}</strong></article><article class="red"><span>Хэтэрсэн / өнөөдөр</span><strong>${overdue}</strong></article><article class="amber"><span>7 хоногийн дотор</span><strong>${upcoming}</strong></article></div><div class="schedule-table-wrap">${rows?`<table class="schedule-table"><thead><tr><th>#</th><th>Тайлангийн нэр</th><th>Давтамж</th><th>Дараагийн хугацаа</th><th>Үлдсэн</th><th>Хариуцах</th><th>Хүлээн авагч</th><th>Тэмдэглэл</th><th></th></tr></thead><tbody>${rows}</tbody></table>`:empty("Хуваарь бүртгэгдээгүй","Эхний тайлагнах үүргээ нэмнэ үү.")}</div><p class="schedule-evidence-note">“Илгээсэн” нь гаднын систем хүргэлтийг батлахгүй. Эрх бүхий хэрэглэгч тайлан илгээснээ тэмдэглэсэн append-only баримт үүсгэж, дараагийн хугацааг нэг мөчлөгөөр урагшлуулна.</p>${reportScheduleDialog()}`}
function reports(){return `${reportTabs()}${state.reportTab==="schedule"?reportScheduleView():managementReport()}`}
async function loadReportSchedules(){try{const out=await api("/api/report-schedules");state.reportSchedules=out.items;state.reportScheduleMeta={today:out.today,timeZone:out.timeZone,capabilities:out.capabilities};if(state.view==="reports"&&state.reportTab==="schedule")render()}catch(err){toast(reportScheduleError(err.message),true)}}
function reportScheduleError(code){return ({REPORT_SCHEDULE_PERMISSION_REQUIRED:"Тайлангийн хуваарьт хандах эрх хүрэлцэхгүй байна.",REPORT_SCHEDULE_RESPONSIBLE_NOT_FOUND:"Сонгосон хариуцагч идэвхгүй эсвэл олдсонгүй.",REPORT_SCHEDULE_VERSION_CONFLICT:"Хуваарийг өөр хэрэглэгч шинэчилсэн байна. Жагсаалтыг дахин ачааллаа.",REPORT_SCHEDULE_RETIRED:"Энэ хуваарь архивлагдсан байна.",REPORT_SCHEDULE_IDEMPOTENCY_CONFLICT:"Давтан хүсэлтийн түлхүүр өөр үйлдэлд ашиглагдсан байна.",REPORT_SCHEDULE_FUTURE_SUBMISSION:"Ирээдүйн огноогоор илгээсэн гэж тэмдэглэх боломжгүй.",REPORT_SCHEDULE_INVALID:"Хуваарийн мэдээллээ шалгана уу."})[code]||code}
function openReportSchedule(itemId=""){const dialog=$("#reportScheduleDialog"),form=$("#reportScheduleForm"),item=state.reportSchedules?.find(value=>value.id===itemId);if(!dialog||!form)return;form.reset();form.elements.id.value=item?.id||"";form.elements.expectedVersion.value=item?.version||"";form.elements.name.value=item?.name||"";form.elements.frequency.value=item?.frequency||"monthly";form.elements.nextDue.value=item?.nextDue||state.reportScheduleMeta.today;form.elements.responsibleUserId.value=item?.responsibleUserId||"";form.elements.responsibleLabel.value=item?.responsibleLabel||"";form.elements.recipient.value=item?.recipient||"";form.elements.warnDays.value=item?.warnDays??7;form.elements.note.value=item?.note||"";$("#reportScheduleDialogTitle").textContent=item?"Хуваарь засах":"Хуваарь нэмэх";dialog.showModal()}
async function saveReportSchedule(form){const value=Object.fromEntries(new FormData(form)),id=value.id;const body={name:value.name,frequency:value.frequency,nextDue:value.nextDue,responsibleUserId:value.responsibleUserId||null,responsibleLabel:value.responsibleLabel,recipient:value.recipient,warnDays:Number(value.warnDays),note:value.note,...(id?{expectedVersion:Number(value.expectedVersion)}:{})};const submit=form.querySelector('button[type="submit"]');submit.disabled=true;try{await api(id?`/api/report-schedules/${id}`:"/api/report-schedules",{method:id?"PATCH":"POST",body:JSON.stringify(body)});$("#reportScheduleDialog").close();await loadReportSchedules();toast(id?"Хуваарь шинэчлэгдлээ.":"Хуваарь нэмэгдлээ.")}catch(err){toast(reportScheduleError(err.message),true);if(err.message==="REPORT_SCHEDULE_VERSION_CONFLICT")await loadReportSchedules()}finally{submit.disabled=false}}
async function submitReportSchedule(itemId){const item=state.reportSchedules?.find(value=>value.id===itemId);if(!item||!confirm(`“${item.name}” тайланг ${item.nextDue} хугацаанд илгээсэн гэж тэмдэглэх үү?`))return;try{const out=await api(`/api/report-schedules/${item.id}/submissions`,{method:"POST",body:JSON.stringify({expectedVersion:item.version,idempotencyKey:crypto.randomUUID()})});await loadReportSchedules();toast(out.nextDue?`Илгээлт бүртгэгдлээ. Дараагийн хугацаа: ${out.nextDue}`:"Нэг удаагийн тайлан илгээгдэж, хуваарь хаагдлаа.")}catch(err){toast(reportScheduleError(err.message),true);if(err.message==="REPORT_SCHEDULE_VERSION_CONFLICT")await loadReportSchedules()}}
async function retireReportSchedule(itemId){const item=state.reportSchedules?.find(value=>value.id===itemId);if(!item)return;const reason=prompt(`“${item.name}” хуваарийг архивлах шалтгаан:`);if(reason===null)return;if(reason.trim().length<3){toast("Архивлах шалтгаан 3-аас доошгүй тэмдэгт байна.",true);return}try{await api(`/api/report-schedules/${item.id}/retire`,{method:"POST",body:JSON.stringify({expectedVersion:item.version,reason:reason.trim()})});await loadReportSchedules();toast("Хуваарь түүхтэйгээ архивлагдлаа.")}catch(err){toast(reportScheduleError(err.message),true);if(err.message==="REPORT_SCHEDULE_VERSION_CONFLICT")await loadReportSchedules()}}
async function exportReport(){const range=state.report?.period||defaultReportRange();try{const response=await fetch(`/api/reports/work-orders.csv?from=${encodeURIComponent(range.from)}&to=${encodeURIComponent(range.to)}`,{headers:{authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error("Тайлан татахад алдаа гарлаа");const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`work-orders-${range.from}-${range.to}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(err){toast(err.message,true)}}
const auditActionLabels={"auth.login":"Системд нэвтэрсэн","organization.bootstrap":"Байгууллага эхлүүлсэн","user.create":"Хэрэглэгч үүсгэсэн","user.update":"Хэрэглэгч шинэчилсэн","user.password_change":"Нууц үгээ сольсон","user.password_reset":"Нууц үг шинэчилсэн","asset.create":"Хөрөнгө үүсгэсэн","asset.update":"Хөрөнгө шинэчилсэн","work_order.create":"Ажил үүсгэсэн","work_order.status_change":"Ажлын төлөв сольсон","work_order.note":"Ажлын тэмдэглэл нэмсэн","attachment.upload":"Файл хавсаргасан","attachment.delete":"Хавсралт устгасан"};
async function loadAudit(filters){if(filters)state.auditFilters={...filters};if(!state.auditFilters.from&&!state.auditFilters.to)state.auditFilters=defaultReportRange();const query=new URLSearchParams({...state.auditFilters,limit:"100"});try{state.audit=await api(`/api/audit?${query}`);if(state.view==="audit"||(state.view==="settings"&&state.settingsTab==="audit"))render()}catch(err){toast(err.message,true)}}
function auditView(){const filters=state.auditFilters,actions=state.audit?.actions||[],toolbar=`<form class="audit-toolbar" id="auditFilterForm"><label>Эхлэх огноо<input name="from" type="date" value="${esc(filters.from||"")}"></label><label>Дуусах огноо<input name="to" type="date" value="${esc(filters.to||"")}"></label><label>Үйлдэл<select name="action"><option value="">Бүх үйлдэл</option>${actions.map(action=>`<option value="${esc(action)}" ${filters.action===action?"selected":""}>${esc(auditActionLabels[action]||action)}</option>`).join("")}</select></label><button class="secondary" type="submit">Шүүх</button></form>`;if(!state.audit)return `${header("ХЯНАЛТ БА ХАРИУЦЛАГА","Аудит журнал","Үйлдлийн бүртгэлийг ачаалж байна...",toolbar)}`;const rows=state.audit.items.map(item=>`<tr><td><strong>${esc(item.user_name||"Систем")}</strong><small>${labels[item.user_role]||item.user_role||"—"}</small></td><td><span class="audit-action">${esc(auditActionLabels[item.action]||item.action)}</span><small>${esc(item.action)}</small></td><td><strong>${esc(item.entity_type)}</strong><small>${esc(item.entity_id||"")}</small></td><td>${dateTime(item.created_at)}</td><td class="audit-ip">${esc(item.ip_address||"—")}</td><td><details class="audit-detail"><summary>Харах</summary><pre>${esc(JSON.stringify(item.detail,null,2))}</pre></details></td></tr>`).join(""),start=state.audit.total?state.audit.offset+1:0,end=Math.min(state.audit.offset+state.audit.limit,state.audit.total);return `${header("ХЯНАЛТ БА ХАРИУЦЛАГА","Аудит журнал","Хэн, хэзээ, ямар үйлдэл хийснийг өөрчлөх боломжгүй журналаас шалгана.",toolbar)}<div class="audit-summary"><span>Нийт <b>${state.audit.total}</b> бүртгэл</span><span>Харуулж буй: <b>${start}–${end}</b></span></div><div class="table-panel">${rows?`<table class="data-table"><thead><tr><th>Хэрэглэгч</th><th>Үйлдэл</th><th>Объект</th><th>Огноо</th><th>IP</th><th>Дэлгэрэнгүй</th></tr></thead><tbody>${rows}</tbody></table><div class="audit-pagination"><button class="secondary" data-audit-offset="${Math.max(0,state.audit.offset-state.audit.limit)}" ${state.audit.offset===0?"disabled":""}>← Өмнөх</button><span>${start}–${end} / ${state.audit.total}</span><button class="secondary" data-audit-offset="${state.audit.offset+state.audit.limit}" ${end>=state.audit.total?"disabled":""}>Дараах →</button></div>`:empty("Аудитын бүртгэл алга","Сонгосон шүүлтүүрээр үйлдэл олдсонгүй.")}</div>`}
function render(){$("#pageContent").innerHTML=state.view==="assets"?assets():state.view==="work-orders"?workOrders():state.view==="lighting"&&typeof lightingView==="function"?lightingView():state.view==="camera"&&typeof cameraView==="function"?cameraView():state.view==="reports"?reports():state.view==="audit"?auditView():state.view==="users"?users():dashboard()}
function renderNotifications(){const count=$("#notificationCount");count.textContent=state.unread>99?"99+":state.unread;count.classList.toggle("hidden",state.unread===0);$("#notificationList").innerHTML=state.notifications.length?state.notifications.map(item=>`<button class="notification-item ${item.read_at?"read":"unread"}" data-notification-id="${item.id}" data-entity-id="${esc(item.entity_id||"")}"><i></i><div><strong>${esc(item.title)}</strong><span>${esc(item.message)}</span><small>${dateTime(item.created_at)}</small></div></button>`).join(""):'<div class="notification-list-empty">Шинэ мэдэгдэл алга</div>'}
function userOptions(selected=""){return '<option value="">Хариуцагчгүй</option>'+state.assignableUsers.map(u=>`<option value="${u.id}" ${u.id===selected?"selected":""}>${esc(u.full_name)} — ${labels[u.role]||u.role}</option>`).join("")}
function workTypeOptions(domain=""){const items=domain?state.workOrderOptions.filter(type=>type.category===domain):state.workOrderOptions;$("#workOrderType").innerHTML='<option value="">Төрөл тодорхойгүй — инженер шийднэ</option>'+items.map(type=>`<option value="${type.id}">${esc(type.name)}${type.department_name?` — ${esc(type.department_name)}`:""}${type.operational_stream?` · ${workStreamLabels[type.operational_stream]}`:""}${type.workflow_name?" · батлах урсгалтай":""}</option>`).join("")}
function serviceAreaOptions(domain=""){const items=domain?state.workServiceAreas.filter(area=>area.domain===domain):state.workServiceAreas;$("#workOrderServiceArea").innerHTML='<option value="">Үйлчилгээний чиглэл сонгохгүй</option>'+items.map(area=>`<option value="${area.id}">${esc(area.icon)} ${esc(area.name)}</option>`).join("")}
function renderWorkTeamPicker(){const form=$("#workOrderForm"),type=state.workOrderOptions.find(item=>item.id===form.elements.workTypeId.value),currentResponsible=form.elements.responsibleEmployeeId.value,checked=new Set([...form.querySelectorAll('[name="executorEmployeeId"]:checked')].map(input=>input.value)),candidates=type?.department_id?state.workEmployees.filter(employee=>employee.department_id===type.department_id):[];$("#workOrderTeamHint").textContent=type?`${type.department_name||"Хариуцах нэгж"} · ${candidates.length} идэвхтэй ажилтан`:"Эхлээд ажлын төрөл сонгоно уу. Сонгосон тасгийн ажилтнууд л харагдана.";form.elements.responsibleEmployeeId.innerHTML='<option value="">Хариуцах хүн сонгохгүй</option>'+candidates.map(employee=>`<option value="${employee.id}" ${employee.id===currentResponsible?"selected":""}>${esc(employee.full_name)} — ${esc(employee.position_title||labels[employee.job_role]||employee.job_role)}</option>`).join("");$("#workOrderExecutors").innerHTML=candidates.length?candidates.map(employee=>`<label class="work-executor-option"><input type="checkbox" name="executorEmployeeId" value="${employee.id}" ${checked.has(employee.id)?"checked":""}><span>${esc(employee.full_name)}<small>${esc(employee.position_title||labels[employee.job_role]||employee.job_role)}</small></span></label>`).join(""):'<small>Энэ ажлын төрөлд хариуцах тасаг эсвэл ажилтан олдсонгүй.</small>'}
function resetWorkOrderForm(){const form=$("#workOrderForm");form.reset();form.dataset.incidentDomain="";form.elements.incidentId.value="";$("#workOrderAssetField").classList.remove("hidden");$("#workOrderSource").classList.add("hidden");$("#workOrderSource").innerHTML="";form.querySelector("[data-form-error]").textContent=""}
function openDialog(id){if(id==="workOrderDialog"){workTypeOptions();serviceAreaOptions();$("#workOrderAsset").innerHTML='<option value="">Хөрөнгө сонгохгүй</option>'+state.assets.map(a=>`<option value="${a.id}">${esc(a.code)} — ${esc(a.name)}</option>`).join("");renderWorkTeamPicker()}if(id==="assetDialog")$("#assetResponsible").innerHTML=userOptions();if(id==="userDialog")$("#userRoleSelect").innerHTML=state.roles.map(r=>`<option value="${r}">${labels[r]||r}</option>`).join("");document.getElementById(id).showModal()}
function openIntakeWork(id){const item=state.workIntake.find(x=>x.id===id);if(!item)return;resetWorkOrderForm();openDialog("workOrderDialog");const form=$("#workOrderForm"),type=state.workOrderOptions.find(x=>x.id===item.suggested_work_type_id);form.dataset.incidentDomain=item.domain;workTypeOptions(item.domain);serviceAreaOptions(item.domain);form.elements.incidentId.value=item.id;form.elements.title.value=item.title;form.elements.workTypeId.value=type?.id||"";form.elements.serviceAreaId.value=item.service_area_id||"";form.elements.operationalStream.value=type?.operational_stream||item.suggested_operational_stream||"";form.elements.category.value="Засвар үйлчилгээ";form.elements.assetId.value="";$("#workOrderAssetField").classList.add("hidden");renderWorkTeamPicker();form.elements.description.value=[item.location&&`Байршил: ${item.location}`,item.object_name&&`Объект: ${item.object_code||item.object_name}`,`Эх бүртгэл: ${intakeDomainLabels[item.domain]||item.domain} / ${item.service_area_name||item.incident_type}`,`Шийдвэрлэх үлдэгдэл: ${Number(item.remaining_quantity||0)}`].filter(Boolean).join("\n");const source=$("#workOrderSource"),related=Number(item.related_open_work_count||0);source.classList.remove("hidden");source.innerHTML=`<strong>Эх асуудалтай холбоотой ажил</strong><span>${esc(item.service_area_name||intakeDomainLabels[item.domain]||item.domain)} · ${date(item.reported_at)}${type?` · Санал: ${esc(type.name)}`:""}${related?` · ⚠ ижил объект дээр ${related} нээлттэй ажилтай`:""}</span>`}
async function attachIntakeToExisting(button){const incidentId=button.dataset.attachIntake,workOrderId=button.dataset.attachWork,item=state.workIntake.find(x=>x.id===incidentId);if(!incidentId||!workOrderId||!item)return;if(!confirm(`“${item.title}” гэмтлийг өмнөх нээлттэй ажилд хэмжих мөрөөр нэмэх үү?`))return;button.disabled=true;try{await api(`/api/work-orders/intake/${incidentId}/attach`,{method:"POST",body:JSON.stringify({workOrderId,idempotencyKey:crypto.randomUUID()})});await refresh();toast("Давтан гэмтлийг өмнөх ажилд хэмжих мөрөөр нэмлээ")}catch(error){button.disabled=false;toast(error.message,true)}}

async function createAsset(e){e.preventDefault();const form=e.currentTarget,error=form.querySelector("[data-form-error]"),value=Object.fromEntries(new FormData(form));value.serialNumber=value.serialNumber||null;value.responsibleUserId=value.responsibleUserId||null;value.acquiredAt=value.acquiredAt||null;value.allocatableQuantity=Number(value.allocatableQuantity);error.textContent="";try{await api("/api/assets",{method:"POST",body:JSON.stringify(value)});form.reset();form.elements.allocatableQuantity.value="1";form.elements.allocationUnit.value="ш";$("#assetDialog").close();await refresh();toast("Хөрөнгө амжилттай бүртгэгдлээ")}catch(err){error.textContent=err.message}}
async function openAsset(id){try{const result=await api(`/api/assets/${id}`),asset=result.item,form=$("#assetDetailForm");form.elements.id.value=asset.id;form.elements.code.value=asset.code;form.elements.name.value=asset.name;form.elements.category.value=asset.category;form.elements.status.value=asset.status;form.elements.serialNumber.value=asset.serial_number||"";form.elements.location.value=asset.location||"";form.elements.allocatableQuantity.value=asset.allocatable_quantity||1;form.elements.allocationUnit.value=asset.allocation_unit||"ш";$("#assetDetailResponsible").innerHTML=userOptions(asset.responsible_user_id);form.elements.acquiredAt.value=asset.acquired_at?String(asset.acquired_at).slice(0,10):"";form.elements.notes.value=asset.notes||"";$("#assetDetailTitle").textContent=`${asset.code} — ${asset.name}`;$("#assetWorkOrders").innerHTML=result.workOrders.length?`<div class="asset-mini-list">${result.workOrders.map(work=>`<button type="button" class="asset-mini-item" data-related-work-id="${work.id}"><div><strong>${esc(work.title)}</strong><small>${date(work.created_at)}</small></div><span class="badge ${work.status}">${labels[work.status]||work.status}</span></button>`).join("")}</div>`:'<div class="asset-empty">Холбогдох ажил бүртгэгдээгүй</div>';$("#assetEvents").innerHTML=result.events.length?result.events.map(event=>`<div class="asset-event"><strong>${event.event_type==="created"?"Хөрөнгө бүртгэсэн":"Мэдээлэл шинэчилсэн"}</strong><small>${esc(event.actor_name||"Систем")} · ${dateTime(event.created_at)}</small></div>`).join(""):'<div class="asset-empty">Өөрчлөлтийн түүх алга</div>';$("#assetOperationalActivity").innerHTML=typeof operationalDossierActivity==="function"?operationalDossierActivity(result):"";$("#assetDetailDialog").showModal()}catch(err){toast(err.message,true)}}
async function updateAsset(e){e.preventDefault();const form=e.currentTarget,error=form.querySelector("[data-form-error]"),value=Object.fromEntries(new FormData(form)),id=value.id;delete value.id;value.serialNumber=value.serialNumber||null;value.responsibleUserId=value.responsibleUserId||null;value.acquiredAt=value.acquiredAt||null;value.allocatableQuantity=Number(value.allocatableQuantity);error.textContent="";try{await api(`/api/assets/${id}`,{method:"PATCH",body:JSON.stringify(value)});await refresh();await openAsset(id);toast("Хөрөнгийн мэдээлэл шинэчлэгдлээ")}catch(err){error.textContent=err.message}}
async function createWork(e){e.preventDefault();const form=e.currentTarget,v=Object.fromEntries(new FormData(form)),error=form.querySelector("[data-form-error]");v.incidentId=v.incidentId||null;v.workTypeId=v.workTypeId||null;v.serviceAreaId=v.serviceAreaId||null;v.operationalStream=v.operationalStream||null;v.assetId=v.incidentId?null:(v.assetId||null);v.assignedTo=v.assignedTo||null;v.responsibleEmployeeId=v.responsibleEmployeeId||null;v.executorEmployeeIds=[...form.querySelectorAll('[name="executorEmployeeId"]:checked')].map(input=>input.value);delete v.executorEmployeeId;v.dueAt=v.dueAt?new Date(v.dueAt).toISOString():null;error.textContent="";try{await api("/api/work-orders",{method:"POST",body:JSON.stringify(v)});resetWorkOrderForm();$("#workOrderDialog").close();await refresh();toast("Ажлын захиалга амжилттай үүслээ")}catch(err){error.textContent=err.message}}
const safetyWorkflowActions=new Set(["safety_authorize_start","safety_return_start","safety_suspend_execution","safety_accept_completion","safety_return_to_execution"]);
function localDateTimeValue(value){const d=new Date(value),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,16)}
async function openSafetyReview(button){button.disabled=true;try{const out=await api(`/api/safety/work-orders/${button.dataset.workflowId}/review-context?action=${encodeURIComponent(button.dataset.workflowAction)}`),item=out.item,form=$("#workSafetyReviewForm"),start=item.reviewType==="start";form.reset();form.elements.workOrderId.value=item.id;form.elements.action.value=item.action;form.elements.templateId.value=item.template_id;form.elements.reviewType.value=item.reviewType;form.elements.idempotencyKey.value=crypto.randomUUID();form.elements.validUntil.value=start?localDateTimeValue(Date.now()+8*60*60*1000):"";$("#workSafetyReviewTitle").textContent=workflowActionLabels[item.action]||"ХАБЭА шалгалт";$("#workSafetyReviewSummary").innerHTML=`<strong>${esc(item.title)}</strong>${esc(item.work_type_name)} · ${esc(item.assigned_name||"Хариуцагчгүй")}<br>${esc(item.template_name)} · v${item.template_version}`;$("#workSafetyRiskFields").classList.toggle("hidden",!start);$("#workSafetyChecklist").innerHTML=item.checklist.map(x=>`<label><input type="checkbox" name="safetyChecklist" value="${esc(x.code)}" data-label="${esc(x.label)}"> <span>${esc(x.label)}${x.required===false?" <small>сонголттой</small>":""}</span></label>`).join("");$("#workSafetyReviewSubmit").textContent=item.action.includes("return")||item.action.includes("suspend")?"Буцаах шийдвэр хадгалах":"Зөвшөөрч хадгалах";form.querySelector("[data-form-error]").textContent="";$("#workSafetyReviewDialog").showModal()}catch(err){toast(err.message,true)}finally{button.disabled=false}}
async function submitSafetyReview(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector("button[type=submit]"),lines=value=>String(value||"").split(/[\n,]+/).map(x=>x.trim()).filter(Boolean),checklist=[...form.querySelectorAll('[name="safetyChecklist"]')].map(x=>({code:x.value,checked:x.checked,note:""})),action=form.elements.action.value,start=form.elements.reviewType.value==="start",validUntil=start&&form.elements.validUntil.value?new Date(form.elements.validUntil.value).toISOString():null;const safetyReview={templateId:form.elements.templateId.value,reviewType:form.elements.reviewType.value,likelihood:start?Number(form.elements.likelihood.value):null,severity:start?Number(form.elements.severity.value):null,hazards:lines(form.elements.hazards.value),controls:lines(form.elements.controls.value),ppe:lines(form.elements.ppe.value),checklist,validUntil,note:form.elements.note.value.trim()};button.disabled=true;form.querySelector("[data-form-error]").textContent="";try{await api(`/api/work-orders/${form.elements.workOrderId.value}/workflow-action`,{method:"POST",body:JSON.stringify({action,note:safetyReview.note,idempotencyKey:form.elements.idempotencyKey.value,safetyReview})});$("#workSafetyReviewDialog").close();await refresh();if(state.view==="safety"&&typeof loadSafety==="function")await loadSafety();toast(workflowActionLabels[action]||"ХАБЭА шийдвэр хадгалагдлаа")}catch(err){form.querySelector("[data-form-error]").textContent=err.message}finally{button.disabled=false}}
async function workflowAction(button){if(safetyWorkflowActions.has(button.dataset.workflowAction))return openSafetyReview(button);let note="";if(button.dataset.workflowAction.includes("return")){note=window.prompt("Буцаах шалтгааныг бичнэ үү:","")||"";if(!note.trim())return}const idempotencyKey=button.dataset.idempotencyKey||crypto.randomUUID();button.dataset.idempotencyKey=idempotencyKey;button.disabled=true;try{await api(`/api/work-orders/${button.dataset.workflowId}/workflow-action`,{method:"POST",body:JSON.stringify({action:button.dataset.workflowAction,note,idempotencyKey})});await refresh();toast(workflowActionLabels[button.dataset.workflowAction]||"Урсгал шинэчлэгдлээ")}catch(err){toast(err.message,true)}finally{button.disabled=false}}
async function changeStatus(el){if(!el.value)return;try{await api(`/api/work-orders/${el.dataset.statusId}/status`,{method:"PATCH",body:JSON.stringify({status:el.value})});await refresh();toast(`Төлөв шинэчлэгдлээ: ${labels[el.value]}`)}catch(err){el.value="";toast(err.message,true)}}
async function changeAssignee(el){try{await api(`/api/work-orders/${el.dataset.assignId}/assign`,{method:"PATCH",body:JSON.stringify({assignedTo:el.value||null})});await refresh();toast("Хариуцагч шинэчлэгдлээ")}catch(err){await refresh();toast(err.message,true)}}
async function claimWork(button){const idempotencyKey=button.dataset.idempotencyKey||crypto.randomUUID();button.dataset.idempotencyKey=idempotencyKey;button.disabled=true;try{await api(`/api/work-orders/${button.dataset.claimWork}/claim`,{method:"POST",body:JSON.stringify({idempotencyKey})});await refresh();toast("Ажлыг таны хариуцлагад авлаа")}catch(err){await refresh();toast(err.message,true)}finally{button.disabled=false}}
function eventText(event){if(event.event_type==="created")return "Ажлын захиалга үүсгэсэн";if(event.event_type==="assigned"){if(event.assignment_history_version===1&&event.assignment_operation==="initial"&&!event.to_assignee_user_id)return "Хариуцагчгүйгээр бүртгэсэн";if(event.assignment_history_version===1&&event.assignment_operation==="reassigned")return `${event.detail?.assignedName||"Шинэ хариуцагч"} ажилтанд дахин хуваарилсан`;return event.detail?.assignedName?`${event.detail.assignedName} ажилтанд хуваарилсан`:"Хариуцагчийг чөлөөлсөн"}if(event.event_type==="status_changed")return `${labels[event.from_status]||event.from_status} → ${labels[event.to_status]||event.to_status}`;if(event.event_type==="workflow_action")return workflowActionLabels[event.detail?.action]||"Батлах урсгалын үйлдэл";return "Гүйцэтгэлийн тэмдэглэл"}
const materialStatusLabels={requested:"Хүссэн",approved:"Баталсан",rejected:"Татгалзсан",issued:"Олгосон",consumed:"Зарцуулсан",cancelled:"Цуцалсан"};
const scopeOutcomeLabels={pending:"Хүлээгдэж буй",in_progress:"Хэсэгчлэн гүйцэтгэсэн",completed:"Гүйцэтгэсэн",blocked:"Шийдэгдээгүй",deferred:"Хойшлуулсан",closed_with_exception:"Үлдэгдлийн шийдвэртэй хаасан"};
function renderWorkScope(result){const target=$("#workScopeItems"),cap=result.scopeCapabilities||{},dispositions=new Map((result.scopeDispositions||[]).filter(item=>item.source_work_order_id===result.item.id).map(item=>[item.source_scope_item_id,item]));if(!target)return;target.innerHTML=(result.scopeItems||[]).length?(result.scopeItems||[]).map(item=>{const disposition=dispositions.get(item.id),editable=cap.canManage&&item.exception_status!=="accepted",decision=cap.canDecide&&item.exception_status==="requested";return `<article class="work-scope-card"><div class="work-scope-head"><div><strong>${esc(item.description)}</strong><small>${esc(item.operational_object_name||item.asset_name||"")} · ${esc(item.item_code)}</small></div><span class="badge ${esc(item.outcome_status)}">${esc(scopeOutcomeLabels[item.outcome_status]||item.outcome_status)}</span></div><div class="work-scope-summary"><span>Төлөвлөсөн <b>${item.planned_quantity} ${esc(item.unit)}</b></span><span>Гүйцэтгэсэн <b>${item.completed_quantity}</b></span><span>Шийдэгдээгүй <b>${item.unresolved_quantity}</b></span><span>Хойшлуулсан <b>${item.deferred_quantity}</b></span></div>${item.exception_reason?`<p class="history-note">${esc(item.exception_reason)}</p>`:""}${editable?`<form class="work-scope-progress" data-scope-progress data-work-id="${result.item.id}" data-scope-id="${item.id}"><label>Гүйцэтгэсэн<input name="completedQuantity" type="number" min="0" max="${item.planned_quantity}" step="0.001" value="${item.completed_quantity}"></label><label>Шийдэгдээгүй<input name="unresolvedQuantity" type="number" min="0" max="${item.planned_quantity}" step="0.001" value="${item.unresolved_quantity}"></label><label>Хойшлуулсан<input name="deferredQuantity" type="number" min="0" max="${item.planned_quantity}" step="0.001" value="${item.deferred_quantity}"></label><label class="wide-field">Үлдэгдлийн шалтгаан<input name="exceptionReason" maxlength="2000" value="${esc(item.exception_reason||"")}" placeholder="Материал, цаг агаар, нэвтрэх боломж..."></label><label class="work-scope-check"><input name="requestException" type="checkbox" ${item.exception_status==="requested"?"checked":""}> Үлдэгдлийн шийдвэр хүсэх</label><button type="submit" class="secondary">Үр дүн хадгалах</button></form>`:""}${decision?`<div class="work-scope-decisions"><button type="button" class="primary" data-scope-decision="follow_up" data-work-id="${result.item.id}" data-scope-id="${item.id}">Үлдэгдлийг самбарт буцаах</button><button type="button" class="secondary" data-scope-decision="accepted_end" data-work-id="${result.item.id}" data-scope-id="${item.id}">Үндэслэлтэй дуусгах</button><button type="button" class="danger" data-scope-reject data-work-id="${result.item.id}" data-scope-id="${item.id}">Буцаах</button></div>`:""}${disposition?`<div class="work-scope-disposition"><strong>${disposition.disposition_type==="follow_up"?"Үлдэгдэл Ажлын самбарт буцсан":"Үндэслэлтэй дуусгасан"}</strong><small>${esc(disposition.reason)} · ${esc(disposition.approved_by_name||"—")} · ${dateTime(disposition.created_at)}</small>${disposition.follow_up_work_order_id?`<button type="button" data-related-work-id="${disposition.follow_up_work_order_id}">${esc(disposition.follow_up_title||"Дараагийн ажил")} →</button>`:""}</div>`:""}</article>`}).join(""):empty("Хэмжигдэх ажлын мөр алга","Гэмтлээс ажил үүсгэхэд хэмжигдэх мөр автоматаар нэмэгдэнэ.");const parents=(result.scopeDispositions||[]).filter(item=>item.follow_up_work_order_id===result.item.id);if(parents.length)target.insertAdjacentHTML("afterbegin",parents.map(item=>`<div class="work-scope-parent"><span>Эх ажлын үлдэгдлээс үүссэн</span><button type="button" data-related-work-id="${item.source_work_order_id}">${esc(item.source_work_title||"Эх ажил")} ←</button><small>${esc(item.reason)} · ${dateTime(item.created_at)}</small></div>`).join(""))}
async function saveScopeProgress(form){const value=Object.fromEntries(new FormData(form));value.completedQuantity=Number(value.completedQuantity);value.unresolvedQuantity=Number(value.unresolvedQuantity);value.deferredQuantity=Number(value.deferredQuantity);value.requestException=form.elements.requestException.checked;try{await api(`/api/work-orders/${form.dataset.workId}/scope-items/${form.dataset.scopeId}`,{method:"PATCH",body:JSON.stringify(value)});await openHistory(form.dataset.workId);await refresh();toast("Ажлын бодит үр дүн хадгалагдлаа")}catch(error){toast(error.message,true)}}
function openScopeDecision(button){const form=$("#workScopeDecisionForm"),followUp=button.dataset.scopeDecision==="follow_up",terminalReasons=new Set(["technical_impossibility","out_of_scope"]);form.reset();form.elements.workOrderId.value=button.dataset.workId;form.elements.scopeItemId.value=button.dataset.scopeId;form.elements.dispositionType.value=button.dataset.scopeDecision;form.elements.idempotencyKey.value=crypto.randomUUID();form.elements.dueAt.required=followUp;form.elements.dueAt.closest("label").classList.toggle("hidden",!followUp);for(const option of form.elements.reasonCode.options)option.disabled=!followUp&&!terminalReasons.has(option.value);if(followUp)form.elements.dueAt.value=localDateTimeValue(Date.now()+7*24*60*60*1000);else form.elements.reasonCode.value="out_of_scope";$("#workScopeDecisionTitle").textContent=followUp?"Үлдэгдлийг Ажлын самбарт буцаах":"Дахин ажил шаардахгүй гэж дуусгах";form.querySelector("[data-form-error]").textContent="";$("#workScopeDecisionDialog").showModal()}
async function saveScopeDecision(event){event.preventDefault();const form=event.currentTarget,value=Object.fromEntries(new FormData(form)),followUp=value.dispositionType==="follow_up";const body={decision:"accepted",note:value.note,disposition:{type:value.dispositionType,reasonCode:value.reasonCode,reason:value.reason,dueAt:followUp?new Date(value.dueAt).toISOString():null,idempotencyKey:value.idempotencyKey}};try{await api(`/api/work-orders/${value.workOrderId}/scope-items/${value.scopeItemId}/exception`,{method:"POST",body:JSON.stringify(body)});$("#workScopeDecisionDialog").close();await openHistory(value.workOrderId);await refresh();toast(followUp?"Үлдэгдэл дараагийн ажил болж самбарт буцлаа":"Үлдэгдлийг үндэслэлтэй дуусгалаа")}catch(error){form.querySelector("[data-form-error]").textContent=error.message}}
async function rejectScopeDecision(button){const note=prompt("Үлдэгдлийн шийдвэрийг буцаах шалтгаан:","");if(!note?.trim())return;try{await api(`/api/work-orders/${button.dataset.workId}/scope-items/${button.dataset.scopeId}/exception`,{method:"POST",body:JSON.stringify({decision:"rejected",note})});await openHistory(button.dataset.workId);await refresh();toast("Үлдэгдлийн шийдвэрийг гүйцэтгэлд буцаалаа")}catch(error){toast(error.message,true)}}
function renderWorkMaterials(result){const c=result.materialCapabilities||{},items=result.materials||[];$("#workMaterials").innerHTML=items.length?`<div class="work-material-list">${items.map(item=>`<div class="work-material-item"><div><strong>${esc(item.sku)} · ${esc(item.item_name)}</strong><small>Хүссэн: ${item.requested_quantity} ${esc(item.unit)}${Number(item.approved_quantity)>0?` · Баталсан: ${item.approved_quantity}`:""}${Number(item.issued_quantity)>0?` · Олгосон: ${item.issued_quantity}`:""}</small><small>${esc(item.reason)} · ${esc(item.requested_by_name||"—")}</small><span class="work-material-status ${item.status}">${esc(materialStatusLabels[item.status]||item.status)}</span></div><div class="work-material-actions">${item.status==="requested"&&c.canApprove?`<button data-material-decision="approved" data-material-id="${item.id}" data-material-work="${result.item.id}" data-material-quantity="${item.requested_quantity}">Батлах</button><button data-material-decision="rejected" data-material-id="${item.id}" data-material-work="${result.item.id}">Татгалзах</button>`:""}${item.status==="issued"&&c.canConsume?`<button data-material-consume="${item.id}" data-material-work="${result.item.id}">Зарцуулалт батлах</button>`:""}</div></div>`).join("")}</div>`:'<small>Материалын хүсэлт бүртгэгдээгүй.</small>';const form=$("#workMaterialForm");form.classList.toggle("hidden",!c.canRequest);form.elements.workOrderId.value=result.item.id;if(c.canRequest)$("#workMaterialItem").innerHTML='<option value="">Материал сонгоно уу</option>'+result.materialOptions.map(item=>`<option value="${item.id}">${esc(item.sku)} · ${esc(item.name)} · үлдэгдэл ${item.total_quantity} ${esc(item.unit)}</option>`).join("")}
function renderWorkParticipants(result){const target=$("#workParticipants"),items=result.participants||[],responsible=items.find(item=>item.participant_role==="responsible"),executors=items.filter(item=>item.participant_role==="executor");target.innerHTML=`<div><small>ХАРИУЦАХ АЖИЛТАН</small><strong>${esc(responsible?.full_name||"Оноогоогүй")}</strong><span>${esc(responsible?.position_title||responsible?.department_name||"—")}</span></div><div><small>ГҮЙЦЭТГЭХ БАГ</small><strong>${executors.length?executors.map(item=>esc(item.full_name)).join(", "):"Оноогоогүй"}</strong><span>${executors.length} ажилтан</span></div>`}
async function openHistory(id){try{const result=await api(`/api/work-orders/${id}/history`);$("#workHistoryTitle").textContent=result.item.title;$("#workNoteForm").elements.workOrderId.value=id;const reviews=(result.safetyReviews||[]).map(review=>`<div class="safety-review-evidence"><strong>${review.review_type==="start"?"ХАБЭА эхлэх зөвшөөрөл":"ХАБЭА дуусгалтын шалгалт"} · ${review.decision==="approved"?"Зөвшөөрсөн":review.decision==="revoked"?"Зогсоосон":"Буцаасан"}</strong><small>${esc(review.template_name)} v${review.template_version} · ${esc(review.actor_name)} · ${dateTime(review.created_at)}${review.risk_score?` · Эрсдэл ${review.risk_score}`:""}${review.valid_until?` · Хүчинтэй ${dateTime(review.valid_until)} хүртэл`:""}</small><p class="history-note">${esc(review.note)}</p></div>`).join("");const events=result.events.length?result.events.map(event=>`<div class="history-item"><i></i><div><strong>${esc(eventText(event))}</strong><small>${esc(event.actor_name||"Систем")} · ${dateTime(event.created_at)}</small>${event.note?`<p class="history-note">${esc(event.note)}</p>`:""}</div></div>`).join(""):empty("Түүх алга","Энэ ажилд үйлдэл бүртгэгдээгүй байна.");$("#workHistory").innerHTML=reviews+events;renderWorkParticipants(result);renderWorkScope(result);renderWorkMaterials(result);$("#workHistoryDialog").showModal()}catch(err){toast(err.message,true)}}
async function requestWorkMaterial(e){e.preventDefault();const form=e.currentTarget,error=form.querySelector("[data-form-error]"),v=Object.fromEntries(new FormData(form));error.textContent="";try{await api(`/api/work-orders/${v.workOrderId}/materials`,{method:"POST",body:JSON.stringify({inventoryItemId:v.inventoryItemId,quantity:v.quantity,reason:v.reason,idempotencyKey:crypto.randomUUID()})});form.elements.quantity.value="";form.elements.reason.value="";await openHistory(v.workOrderId);toast("Материалын хүсэлт бүртгэгдлээ")}catch(err){error.textContent=err.message}}
async function decideWorkMaterial(button){const approved=button.dataset.materialDecision==="approved",quantity=approved?Number(prompt("Батлах тоо хэмжээ:",button.dataset.materialQuantity)):undefined;if(approved&&(!quantity||quantity<=0))return;const note=prompt(approved?"Шийдвэрийн тайлбар (заавал биш):":"Татгалзах шалтгаан:","");if(note===null||(!approved&&!note.trim()))return;try{await api(`/api/work-orders/${button.dataset.materialWork}/materials/${button.dataset.materialId}/decision`,{method:"POST",body:JSON.stringify({decision:button.dataset.materialDecision,approvedQuantity:quantity,note})});await openHistory(button.dataset.materialWork);toast(approved?"Материалын хүсэлт батлагдлаа":"Материалын хүсэлт татгалзагдлаа")}catch(err){toast(err.message,true)}}
async function consumeWorkMaterial(button){if(!confirm("Олгосон материал энэ ажилд зарцуулагдсаныг батлах уу?"))return;try{await api(`/api/work-orders/${button.dataset.materialWork}/materials/${button.dataset.materialConsume}/consume`,{method:"POST",body:"{}"});await openHistory(button.dataset.materialWork);toast("Материалын зарцуулалт баталгаажлаа")}catch(err){toast(err.message,true)}}
async function addWorkNote(e){e.preventDefault();const form=e.currentTarget,error=form.querySelector("[data-form-error]"),value=Object.fromEntries(new FormData(form));error.textContent="";try{await api(`/api/work-orders/${value.workOrderId}/notes`,{method:"POST",body:JSON.stringify({note:value.note})});form.elements.note.value="";await openHistory(value.workOrderId);toast("Тэмдэглэл нэмэгдлээ")}catch(err){error.textContent=err.message}}
async function openNotification(button){try{await api(`/api/notifications/${button.dataset.notificationId}/read`,{method:"PATCH",body:"{}"});$("#notificationPanel").classList.add("hidden");state.workFilter="open";setView("work-orders");await refresh();if(button.dataset.entityId)await openHistory(button.dataset.entityId)}catch(err){toast(err.message,true)}}
async function readAllNotifications(){try{await api("/api/notifications/read-all",{method:"PATCH",body:"{}"});await refresh();toast("Бүх мэдэгдлийг уншсанд тооцлоо")}catch(err){toast(err.message,true)}}
async function createUser(e){e.preventDefault();const form=e.currentTarget,error=form.querySelector("[data-form-error]");error.textContent="";try{await api("/api/users",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();$("#userDialog").close();await refresh();toast("Хэрэглэгч амжилттай үүслээ")}catch(err){error.textContent=err.message}}
async function toggleUser(button){const active=button.dataset.userActive==="true";try{await api(`/api/users/${button.dataset.userId}`,{method:"PATCH",body:JSON.stringify({active:!active})});await refresh();toast(active?"Хэрэглэгч идэвхгүй боллоо":"Хэрэглэгч идэвхжлээ")}catch(err){toast(err.message,true)}}
async function changePassword(e){e.preventDefault();const form=e.currentTarget,v=Object.fromEntries(new FormData(form)),error=form.querySelector("[data-form-error]");error.textContent="";if(v.newPassword!==v.confirmPassword){error.textContent="Шинэ нууц үг таарахгүй байна";return}try{await api("/api/auth/change-password",{method:"POST",body:JSON.stringify({currentPassword:v.currentPassword,newPassword:v.newPassword})});form.reset();$("#passwordDialog").close();toast("Нууц үг амжилттай солигдлоо")}catch(err){error.textContent=err.message}}
function formatBytes(bytes){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
async function loadAttachments(type,id,target){try{const result=await api(`/api/attachments/entity/${type}/${id}`),management=["director","chief_engineer"].includes(state.user.role);$(target).innerHTML=result.items.length?result.items.map(item=>`<div class="attachment-item"><div><strong>${esc(item.original_name)}</strong><small>${formatBytes(Number(item.size_bytes))} · ${esc(item.uploaded_by_name||"Хэрэглэгч")} · ${dateTime(item.created_at)}</small></div><div class="attachment-actions"><button data-download-attachment="${item.id}" data-file-name="${esc(item.original_name)}">Татах</button>${item.uploaded_by===state.user.id||management?`<button class="danger" data-delete-attachment="${item.id}" data-attachment-type="${type}" data-attachment-entity="${id}" data-attachment-target="${target}">Устгах</button>`:""}</div></div>`).join(""):'<div class="attachment-empty">Хавсаргасан файл алга</div>'}catch(err){toast(err.message,true)}}
async function showAsset(id){state.selectedAssetId=id;await openAsset(id);await loadAttachments("assets",id,"#assetAttachments")}
async function showHistory(id){state.selectedWorkId=id;await openHistory(id);await loadAttachments("work-orders",id,"#workAttachments")}
async function uploadAttachment(type,id,input,target){const file=input.files[0];if(!file)return toast("Файл сонгоно уу",true);const data=new FormData();data.append("file",file);try{const response=await fetch(`/api/attachments/entity/${type}/${id}`,{method:"POST",headers:{authorization:`Bearer ${state.token}`},body:data}),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Файл upload хийхэд алдаа гарлаа");input.value="";await loadAttachments(type,id,target);toast("Файл амжилттай хавсаргалаа")}catch(err){toast(err.message,true)}}
async function downloadAttachment(button){try{const response=await fetch(`/api/attachments/file/${button.dataset.downloadAttachment}`,{headers:{authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error("Файл татахад алдаа гарлаа");const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=button.dataset.fileName;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(err){toast(err.message,true)}}
async function deleteAttachment(button){try{await api(`/api/attachments/file/${button.dataset.deleteAttachment}`,{method:"DELETE"});await loadAttachments(button.dataset.attachmentType,button.dataset.attachmentEntity,button.dataset.attachmentTarget);toast("Хавсралт устгагдлаа")}catch(err){toast(err.message,true)}}
document.addEventListener("click",e=>{const nav=e.target.closest("[data-view]"),open=e.target.closest("[data-open]"),close=e.target.closest("[data-close]"),go=e.target.closest("[data-go]"),user=e.target.closest("[data-user-id]"),history=e.target.closest("[data-history-id]"),intake=e.target.closest("[data-intake-id]"),attachIntake=e.target.closest("[data-attach-intake]"),claim=e.target.closest("[data-claim-work]"),filter=e.target.closest("[data-work-filter]"),intakeFilter=e.target.closest("[data-intake-filter]"),areaFilter=e.target.closest("[data-work-area-filter]"),notification=e.target.closest("[data-notification-id]"),asset=e.target.closest("[data-asset-id]"),related=e.target.closest("[data-related-work-id]"),download=e.target.closest("[data-download-attachment]"),remove=e.target.closest("[data-delete-attachment]"),auditPage=e.target.closest("[data-audit-offset]"),workflow=e.target.closest("[data-workflow-action]"),materialDecision=e.target.closest("[data-material-decision]"),materialConsume=e.target.closest("[data-material-consume]"),reportPreset=e.target.closest("[data-report-preset]"),reportTab=e.target.closest("[data-report-tab]"),scheduleCreate=e.target.closest("[data-report-schedule-create]"),scheduleEdit=e.target.closest("[data-report-schedule-edit]"),scheduleSubmit=e.target.closest("[data-report-schedule-submit]"),scheduleRetire=e.target.closest("[data-report-schedule-retire]");if(nav)setView(nav.dataset.view);if(go){if(go.dataset.reportTabTarget)state.reportTab=go.dataset.reportTabTarget;setView(go.dataset.go)}if(open){if(open.dataset.open==="workOrderDialog")resetWorkOrderForm();openDialog(open.dataset.open)}if(close)document.getElementById(close.dataset.close).close();if(user)toggleUser(user);if(history)showHistory(history.dataset.historyId);if(intake)openIntakeWork(intake.dataset.intakeId);if(attachIntake)attachIntakeToExisting(attachIntake);if(claim)claimWork(claim);if(filter){state.workFilter=filter.dataset.workFilter;render()}if(intakeFilter){state.intakeFilter=intakeFilter.dataset.intakeFilter;state.workAreaFilter="all";render()}if(areaFilter){state.workAreaFilter=areaFilter.dataset.workAreaFilter;render()}if(notification)openNotification(notification);if(asset)showAsset(asset.dataset.assetId);if(related){$("#assetDetailDialog").close();showHistory(related.dataset.relatedWorkId)}if(download)downloadAttachment(download);if(remove)deleteAttachment(remove);if(auditPage)loadAudit({...state.auditFilters,offset:auditPage.dataset.auditOffset});if(workflow)workflowAction(workflow);if(materialDecision)decideWorkMaterial(materialDecision);if(materialConsume)consumeWorkMaterial(materialConsume);if(reportPreset){const range=reportPresetRange(reportPreset.dataset.reportPreset);loadReport(range.from,range.to)}if(reportTab){state.reportTab=reportTab.dataset.reportTab;render();if(state.reportTab==="overview"&&!state.report)loadReport();if(state.reportTab==="schedule"&&!state.reportSchedules)loadReportSchedules()}if(scheduleCreate)openReportSchedule();if(scheduleEdit)openReportSchedule(scheduleEdit.dataset.reportScheduleEdit);if(scheduleSubmit)submitReportSchedule(scheduleSubmit.dataset.reportScheduleSubmit);if(scheduleRetire)retireReportSchedule(scheduleRetire.dataset.reportScheduleRetire);if(e.target.closest("[data-report-schedule-cancel]"))$("#reportScheduleDialog")?.close();if(e.target.closest("#printReportButton"))window.print();if(e.target.closest("#exportReportButton"))exportReport()});
document.addEventListener("click",e=>{const scopeDecision=e.target.closest("[data-scope-decision]"),scopeReject=e.target.closest("[data-scope-reject]");if(scopeDecision)openScopeDecision(scopeDecision);if(scopeReject)rejectScopeDecision(scopeReject)});
document.addEventListener("submit",e=>{if(e.target.matches("[data-scope-progress]")){e.preventDefault();saveScopeProgress(e.target)}if(e.target.id==="workScopeDecisionForm"){e.preventDefault();saveScopeDecision(e)}if(e.target.id==="reportFilterForm"){e.preventDefault();const value=Object.fromEntries(new FormData(e.target));loadReport(value.from,value.to)}if(e.target.id==="reportScheduleForm"){e.preventDefault();saveReportSchedule(e.target)}if(e.target.id==="auditFilterForm"){e.preventDefault();loadAudit({...Object.fromEntries(new FormData(e.target)),offset:"0"})}});
document.addEventListener("change",e=>{if(e.target.matches("[data-status-id]"))changeStatus(e.target);if(e.target.matches("[data-assign-id]"))changeAssignee(e.target);if(e.target.id==="workOrderType")renderWorkTeamPicker()});
$("#assetAttachmentUpload").addEventListener("click",()=>uploadAttachment("assets",state.selectedAssetId,$("#assetAttachmentFile"),"#assetAttachments"));$("#workAttachmentUpload").addEventListener("click",()=>uploadAttachment("work-orders",state.selectedWorkId,$("#workAttachmentFile"),"#workAttachments"));$("#notificationButton").addEventListener("click",()=>$("#notificationPanel").classList.toggle("hidden"));$("#readAllButton").addEventListener("click",readAllNotifications);$("#loginForm").addEventListener("submit",login);$("#logoutButton").addEventListener("click",()=>logout());$("#topLogoutButton").addEventListener("click",()=>logout());$("#assetForm").addEventListener("submit",createAsset);$("#assetDetailForm").addEventListener("submit",updateAsset);$("#workOrderForm").addEventListener("submit",createWork);$("#workNoteForm").addEventListener("submit",addWorkNote);$("#workMaterialForm").addEventListener("submit",requestWorkMaterial);$("#workSafetyReviewForm").addEventListener("submit",submitSafetyReview);$("#userForm").addEventListener("submit",createUser);$("#passwordForm").addEventListener("submit",changePassword);if(state.token)window.addEventListener("DOMContentLoaded",()=>loadSession(),{once:true});
